"""Write `src/http/mime_table.rs` from `python_constants.json` (Python 3.13's built-in `mimetypes`
tables, as in the panel image, which has no /etc/mime.types)."""
from __future__ import annotations

import json
from pathlib import Path

HERE = Path(__file__).resolve().parent
constants = json.loads((HERE / "python_constants.json").read_text())


def table(name: str, items: dict) -> str:
    rows = "\n".join(f"    ({json.dumps(key)}, {json.dumps(value)})," for key, value in sorted(items.items()))
    return f"pub(crate) const {name}: &[(&str, &str)] = &[\n{rows}\n];\n"


text = (
    "//! Generated by `tests/fixtures/gen_mime_table.py` from Python 3.13's built-in `mimetypes`\n"
    "//! tables (`MimeTypes(filenames=()).types_map[True]`, `encodings_map`, `suffix_map`). Do not edit.\n\n"
    + table("TYPES_MAP", constants["types_map"]) + "\n"
    + table("ENCODINGS_MAP", constants["encodings_map"]) + "\n"
    + table("SUFFIX_MAP", constants["suffix_map"])
)
(HERE.parents[1] / "src" / "http" / "mime_table.rs").write_text(text)
print(len(constants["types_map"]))
